<script setup>import { Head,Link,useForm } from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({managedUser:Object}); const editing=!!props.managedUser; const form=useForm({first_name:props.managedUser?.first_name||'',last_name:props.managedUser?.last_name||'',mobile:props.managedUser?.mobile||'',email:props.managedUser?.email||'',role:props.managedUser?.role||'STUDENT',is_active:props.managedUser?.is_active??true,password:'',password_confirmation:''}); const submit=()=>editing?form.put(`/admin/users/${props.managedUser.id}`):form.post('/admin/users');</script>
<template><AppLayout><Head :title="editing?'ویرایش کاربر':'کاربر جدید'"/><section class="rounded-2xl border bg-white p-6"><h1 class="mb-6 text-xl font-bold">{{ editing?'ویرایش کاربر':'ایجاد کاربر' }}</h1><form class="grid gap-4 md:grid-cols-2" @submit.prevent="submit"><div><label>نام</label><input v-model="form.first_name"><p class="text-sm text-red-600">{{ form.errors.first_name }}</p></div><div><label>نام خانوادگی</label><input v-model="form.last_name"><p class="text-sm text-red-600">{{ form.errors.last_name }}</p></div><div><label>شماره موبایل</label><input v-model="form.mobile" dir="ltr"><p class="text-sm text-red-600">{{ form.errors.mobile }}</p></div><div><label>ایمیل (اختیاری)</label><input v-model="form.email" type="email" dir="ltr"><p class="text-sm text-red-600">{{ form.errors.email }}</p></div><div><label>نقش</label><select v-model="form.role" :disabled="managedUser?.role==='ADMIN'"><option value="TEACHER">مدرس</option><option value="STUDENT">هنرجو</option><option v-if="managedUser?.role==='ADMIN'" value="ADMIN">مدیر</option></select></div><label class="flex items-center gap-2 self-end pb-2"><input v-model="form.is_active" type="checkbox" class="h-4 w-4"> حساب فعال باشد</label><div><label>{{ editing?'رمز جدید (اختیاری)':'رمز عبور' }}</label><input v-model="form.password" type="password"><p class="text-sm text-red-600">{{ form.errors.password }}</p></div><div><label>تکرار رمز عبور</label><input v-model="form.password_confirmation" type="password"></div><div class="flex gap-3 md:col-span-2"><button class="rounded-xl bg-teal-700 px-5 py-2.5 font-bold text-white">ذخیره</button><Link href="/admin/users" class="rounded-xl border px-5 py-2.5">انصراف</Link></div></form></section></AppLayout></template>
